# Let's analyze patterns more systematically
# Maybe each connected component of a certain color transforms in a specific way?

def find_connected_components(grid):
    """Find all connected components with their bounding boxes"""
    h, w = grid.shape
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r,c] not in visited:
                # BFS to find component
                comp_pixels = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp_pixels.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr,nc] == grid[cr,cc] and (nr,nc) not in visited:
                            stack.append((nr, nc))
                components.append({
                    'value': grid[r,c],
                    'pixels': comp_pixels,
                    'count': len(comp_pixels)
                })
    return components

components = find_connected_components(arr)
print(f"Total connected components: {len(components)}")
